<?php
namespace App\Extensions\ChatbotWhatsapp\System\Http\Controllers;
use App\Extensions\ChatbotWhatsapp\System\Models\OutboundMessage; use App\Extensions\ChatbotWhatsapp\System\Services\MessagingRuntime; use App\Http\Controllers\Controller; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class MessagingRuntimeController extends Controller { public function send(Request $r,MessagingRuntime $runtime):JsonResponse{$d=$r->validate(['provider'=>'required|string','channel'=>'required|in:whatsapp,sms,mms','to'=>'required|string','text'=>'nullable|string','media'=>'nullable|array','template'=>'nullable|array','scheduled_at'=>'nullable|date']);return response()->json($runtime->send($d),202);} public function retry(OutboundMessage $message,MessagingRuntime $runtime):JsonResponse{return response()->json($runtime->retry($message),202);} public function health():JsonResponse{return response()->json(['ok'=>true,'extension'=>'chatbot-whatsapp','channels'=>['whatsapp','sms','mms'],'version'=>'2.0.0']);} }
